CREATE TABLE IF NOT EXISTS payments.payments (uuid UUID PRIMARY KEY, payer_uuid UUID NOT NULL REFERENCES iam.users(uuid) ON DELETE RESTRICT, amount NUMERIC(18,2) NOT NULL CHECK (amount >= 0), currency CHAR(3) NOT NULL CHECK (currency = UPPER(currency)), status VARCHAR(20) NOT NULL CHECK (status IN ('pending', 'completed', 'failed', 'refunded')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
